import{_ as s,l as o,o as a,c as l,v as t,p as c,x as i,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"异构核调度","description":"","frontmatter":{"title":"异构核调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heterogeneous-core-sched.md","filePath":"cs/heterogeneous-core-sched.md","lastUpdated":1789023840000}'),h={name:"cs/heterogeneous-core-sched.md"};function u(E,e,_,m,f,A){const r=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="异构核调度" tabindex="-1">异构核调度 <a class="header-anchor" href="#异构核调度" aria-label="Permalink to &quot;异构核调度&quot;">​</a></h1><div class="epigraph"><p>big.LITTLE / 混合核把高容量核与高能效核放在同一系统：调度器要按任务 util 与容量把人放到「够用且更省」的那边。</p><footer>—— 据 ARM big.LITTLE 软件说明；Linux 对 asymmetric CPU capacity 的文档</footer></div><p><a href="/cs/eas-scheduling">EAS</a> 的模型在异构上才真正分化。<a href="/cs/sched-domains">调度域</a> 会出现不同 <code>cpu_capacity</code>。缺口是 <strong>非对称容量</strong>：不是再讲 SMT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小核容量 400、大核 1024（相对值）。把重任务放小核会拖尾；把永远睡的放小核省电。缺口：misfit 迁移（任务 util 超过本核容量则上迁）；用户 cpuset 可能只留小核；与 <a href="/cs/thp">THP</a> 无关。本课不把 Intel 的 E-core 品牌当目录。</p><p><span class="marginnote">中间层核（mid）使策略更碎。容量随频率变，EAS 同时看 freq。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>wake：过滤容量不足的 CPU。idle load balance：把 misfit 拉到大核。对照 <a href="/cs/rss-multiqueue">RSS</a>：硬件哈希不管任务轻重；这里必须看 util。对照 <a href="/cs/blkio-cgroup">blkio</a>：I/O 权重不改变 CPU 容量。</p>',8)),(a(),c(p,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%20util%22%5D%20--%3E%20CAP%5B%22CPU%20%E5%AE%B9%E9%87%8F%22%5D%0A%20%20CAP%20--%3E%7C%22%E4%B8%8D%E5%A4%9F%22%7C%20UP%5B%22%E8%BF%81%E5%88%B0%E6%9B%B4%E5%A4%A7%E6%A0%B8%22%5D%0A%20%20CAP%20--%3E%7C%22%E8%BF%87%E6%9D%80%22%7C%20DOWN%5B%22%E5%8F%AF%E4%B8%8B%E5%88%B0%E8%83%BD%E6%95%88%E6%A0%B8%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>异构调度把单 ISA 多微架构收成容量数字，使手机能在续航与跟手之间折中。错误的容量表等于永久 misfit 或永远大核。不要写成购买指南。与实时：RT 任务常钉大核，后课 deadline。</p><p>调试：看 <code>cpu_capacity</code> 与任务 <code>util_avg</code>。</p><p>实现上：misfit 是「util 超过本 CPU 容量」，不是 nice。小核跑满的轻任务不应上迁。cluster 迁移迟滞避免在大小核间抖。 读法上只引用<a href="/cs/eas-scheduling">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>异构核调度</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cluster 迁移的全部迟滞参数。不保证虚拟机把异构暴露给客户。下一课硬时限：SCHED_DEADLINE。</p><p>版本字段会变，课序钉的是机制对象「异构核调度」，不是某一主线内核的结构体名。 后课默认：任务可按容量在大小核间迁移。CPU 带宽与截止时间调度类，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异构核用容量数字决定上下迁。</li><li>misfit 防止重任务卡在小核。</li><li>SCHED_DEADLINE 是下一课。</li><li>出处：Linux asymmetric capacity；ARM big.LITTLE。</li></ul>',11))])}const P=s(h,[["render",u]]);export{B as __pageData,P as default};
